// Generated by AI (UnitTest MCP)
//! `GET /api/v1/repositories/:id/graph` (ADR-0087's `bounded_neighborhood`,
//! wired up for the first time): a bounded neighborhood of the repository's
//! projected context graph.

use std::time::SystemTime;

use axum::{
    extract::{Path, Query, State},
    http::StatusCode,
    Json,
};
use serde::{Deserialize, Serialize};

use ackplane_server::projection::{BoundedNeighborhood, ProjectedNode};

use super::enrolled_or_not_found;
use crate::{unix_seconds, AppState};

const DEFAULT_GRAPH_DEPTH: i32 = 2;
const MAX_GRAPH_DEPTH: i32 = 4;
const DEFAULT_GRAPH_MAX_NODES: i32 = 75;
const MAX_GRAPH_MAX_NODES: i32 = 300;
const DEFAULT_GRAPH_MAX_FANOUT: i32 = 12;
const MAX_GRAPH_MAX_FANOUT: i32 = 30;
/// How many nodes `Projector::sample_nodes` seeds the view with when the
/// caller has not chosen a seed yet.
const DEFAULT_SEED_SAMPLE: i64 = 8;

/// `GET /api/v1/repositories/:repository_id/graph` query parameters
/// (ADR-0087's existing `bounded_neighborhood`, wired up for the first
/// time). All optional: an absent `seeds` falls back to
/// `Projector::sample_nodes`, the most recently touched nodes.
#[derive(Deserialize)]
pub struct GraphQuery {
    seeds: Option<String>,
    depth: Option<i32>,
    max_nodes: Option<i32>,
    max_fanout: Option<i32>,
}

#[derive(Serialize)]
pub struct GraphResponse {
    nodes: Vec<GraphNodeSummary>,
    edges: Vec<GraphEdgeSummary>,
    projection_stream_position: Option<i64>,
    projected_at_seconds: Option<u64>,
}

#[derive(Serialize)]
struct GraphNodeSummary {
    node_id: String,
    node_type: String,
    label: String,
    depth: i32,
}

impl From<ProjectedNode> for GraphNodeSummary {
    fn from(node: ProjectedNode) -> Self {
        Self {
            node_id: node.node_id,
            node_type: node.node_type,
            label: node.label,
            depth: node.depth,
        }
    }
}

#[derive(Serialize)]
struct GraphEdgeSummary {
    source_id: String,
    target_id: String,
    relation: String,
    effective_weight: f64,
}

/// `W_eff = W_base * 2^(-Δt_hours / half_life)`, mirroring
/// `mindleak_core::decay::effective_weight` and the SQL this same formula
/// already runs as inside `bounded_neighborhood`'s own frontier ordering --
/// computed here only for display, never stored. Clamps `elapsed <= 0` to
/// `base_weight` directly, the same guard the Rust reference implementation
/// and `knowledge_store`'s `EFFECTIVE_WEIGHT_SQL` both apply.
fn effective_weight(
    base_weight: f64,
    half_life_hours: f64,
    updated_at: SystemTime,
    now: SystemTime,
) -> f64 {
    let elapsed_hours = match now.duration_since(updated_at) {
        Ok(elapsed) if !elapsed.is_zero() => elapsed.as_secs_f64() / 3600.0,
        _ => return base_weight,
    };
    base_weight * 2.0_f64.powf(-elapsed_hours / half_life_hours)
}

/// Parses the `seeds` query parameter into trimmed, non-empty node ids.
/// `None` (an absent parameter, or one that is entirely whitespace) is the
/// caller's signal to fall back to `Projector::sample_nodes` -- distinct
/// from `Some` with an empty `Vec`, which is what an explicit but entirely
/// blank value (e.g. `",,,"`) parses to: the caller asked for nothing, not
/// for the default sample.
fn parse_graph_seeds(raw: Option<&str>) -> Option<Vec<String>> {
    let raw = raw?;
    if raw.trim().is_empty() {
        return None;
    }
    Some(
        raw.split(',')
            .map(str::trim)
            .filter(|seed| !seed.is_empty())
            .map(str::to_string)
            .collect(),
    )
}

pub async fn repository_graph(
    State(state): State<AppState>,
    Path(repository_id): Path<String>,
    Query(query): Query<GraphQuery>,
) -> Result<Json<GraphResponse>, StatusCode> {
    enrolled_or_not_found(&state, &repository_id, "graph query").await?;

    let depth = query
        .depth
        .unwrap_or(DEFAULT_GRAPH_DEPTH)
        .clamp(1, MAX_GRAPH_DEPTH);
    let max_nodes = query
        .max_nodes
        .unwrap_or(DEFAULT_GRAPH_MAX_NODES)
        .clamp(1, MAX_GRAPH_MAX_NODES);
    let max_fanout = query
        .max_fanout
        .unwrap_or(DEFAULT_GRAPH_MAX_FANOUT)
        .clamp(1, MAX_GRAPH_MAX_FANOUT);

    let seeds: Vec<String> = match parse_graph_seeds(query.seeds.as_deref()) {
        Some(seeds) => seeds,
        None => {
            match state
                .projector
                .sample_nodes(&state.tenant_id, &repository_id, DEFAULT_SEED_SAMPLE)
                .await
            {
                Ok(nodes) => nodes.into_iter().map(|node| node.node_id).collect(),
                Err(error) => {
                    tracing::error!(%error, "Bridge default graph seed sampling failed");
                    return Err(StatusCode::INTERNAL_SERVER_ERROR);
                }
            }
        }
    };

    // No seed and nothing to sample (never projected, or a genuinely empty
    // graph): an empty response is the honest answer, not an error.
    if seeds.is_empty() {
        return Ok(Json(GraphResponse {
            nodes: Vec::new(),
            edges: Vec::new(),
            projection_stream_position: None,
            projected_at_seconds: None,
        }));
    }

    match state
        .projector
        .bounded_neighborhood(
            &state.tenant_id,
            &repository_id,
            &seeds,
            depth,
            max_nodes,
            max_fanout,
        )
        .await
    {
        Ok(BoundedNeighborhood {
            nodes,
            edges,
            freshness,
        }) => {
            let now = SystemTime::now();
            Ok(Json(GraphResponse {
                nodes: nodes.into_iter().map(GraphNodeSummary::from).collect(),
                edges: edges
                    .into_iter()
                    .map(|edge| GraphEdgeSummary {
                        effective_weight: effective_weight(
                            edge.base_weight,
                            edge.half_life_hours,
                            edge.updated_at,
                            now,
                        ),
                        source_id: edge.source_id,
                        target_id: edge.target_id,
                        relation: edge.relation,
                    })
                    .collect(),
                projection_stream_position: freshness.as_ref().map(|f| f.stream_position),
                projected_at_seconds: freshness.and_then(|f| unix_seconds(f.projected_at)),
            }))
        }
        Err(error) => {
            tracing::error!(%error, "Bridge repository graph query failed");
            Err(StatusCode::INTERNAL_SERVER_ERROR)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn effective_weight_is_unchanged_at_zero_elapsed_time() {
        let now = SystemTime::UNIX_EPOCH + Duration::from_secs(10_000);
        assert_eq!(effective_weight(1.0, 168.0, now, now), 1.0);
    }

    #[test]
    fn effective_weight_halves_after_one_half_life() {
        let updated_at = SystemTime::UNIX_EPOCH + Duration::from_secs(10_000);
        let now = updated_at + Duration::from_secs(168 * 3600);
        assert!((effective_weight(1.0, 168.0, updated_at, now) - 0.5).abs() < 1e-9);
    }

    #[test]
    fn effective_weight_clamps_a_stale_updated_at_in_the_future_to_the_base_weight() {
        let now = SystemTime::UNIX_EPOCH + Duration::from_secs(10_000);
        let updated_at = now + Duration::from_secs(60);
        assert_eq!(effective_weight(1.0, 168.0, updated_at, now), 1.0);
    }

    #[test]
    fn parse_graph_seeds_falls_back_to_sampling_when_absent() {
        assert_eq!(parse_graph_seeds(None), None);
    }

    #[test]
    fn parse_graph_seeds_falls_back_to_sampling_when_whitespace_only() {
        assert_eq!(parse_graph_seeds(Some("   ")), None);
    }

    #[test]
    fn parse_graph_seeds_returns_a_single_trimmed_seed() {
        assert_eq!(
            parse_graph_seeds(Some(" artifact:foo.rs ")),
            Some(vec!["artifact:foo.rs".to_string()])
        );
    }

    #[test]
    fn parse_graph_seeds_splits_and_trims_multiple_seeds() {
        assert_eq!(
            parse_graph_seeds(Some("artifact:a.rs , artifact:b.rs")),
            Some(vec![
                "artifact:a.rs".to_string(),
                "artifact:b.rs".to_string()
            ])
        );
    }

    #[test]
    fn parse_graph_seeds_drops_empty_entries_between_commas() {
        assert_eq!(
            parse_graph_seeds(Some("artifact:a.rs,,artifact:b.rs")),
            Some(vec![
                "artifact:a.rs".to_string(),
                "artifact:b.rs".to_string()
            ])
        );
    }

    #[test]
    fn parse_graph_seeds_returns_an_empty_list_for_an_explicit_but_entirely_blank_value() {
        // Distinct from `None`: the caller supplied a `seeds` value, so this
        // must NOT fall back to Projector::sample_nodes -- it asked for
        // nothing, and nothing is the honest answer.
        assert_eq!(parse_graph_seeds(Some(",,,")), Some(Vec::new()));
    }

    #[test]
    fn graph_node_summary_from_projected_node_maps_every_field() {
        let summary = GraphNodeSummary::from(ProjectedNode {
            node_id: "artifact:foo.rs".to_string(),
            node_type: "artifact".to_string(),
            label: "foo.rs".to_string(),
            depth: 2,
        });

        assert_eq!(
            serde_json::to_value(summary).expect("summary serializes"),
            serde_json::json!({
                "node_id": "artifact:foo.rs",
                "node_type": "artifact",
                "label": "foo.rs",
                "depth": 2,
            })
        );
    }
}
